#!/usr/bin/env node
/**
 * Generates the TypeScript, Swift and Kotlin notification event tables from
 * specs/NotificationEvents.json. The generated files are checked in; `--check` fails when they are
 * stale.
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SPEC_PATH = path.join(ROOT, 'specs', 'NotificationEvents.json');
const TS_PATH = path.join(ROOT, 'src', 'Structs', 'NotificationEvents.generated.ts');
const SWIFT_PATH = path.join(ROOT, 'ios', 'TricordarrKit', 'Generated', 'NotificationEvents.generated.swift');
const KOTLIN_PATH = path.join(
  ROOT,
  'android',
  'app',
  'src',
  'main',
  'java',
  'com',
  'tricordarr',
  'push',
  'NotificationEventTable.generated.kt',
);

const HEADER = [
  '// @generated by scripts/generate-notification-events.js from specs/NotificationEvents.json.',
  '// DO NOT EDIT BY HAND. Change the JSON, then run `npm run codegen:notifications`.',
].join('\n');

const KNOWN_KEYS = {
  root: ['version', 'channelGroups', 'channels', 'events', 'unposted'],
  group: ['name', 'description'],
  channel: ['name', 'group', 'description', 'badge', 'vibrationPattern', 'settingsChannel'],
  event: ['channel', 'title', 'doc', 'note', 'url', 'markAsReadUrl', 'autoCancel', 'ongoing', 'messaging'],
  unposted: ['title', 'doc', 'note', 'deprecated', 'settingsChannel'],
};

const REQUIRED_KEYS = {
  root: ['channelGroups', 'channels', 'events', 'unposted'],
  group: ['name', 'description'],
  channel: ['name', 'group', 'description'],
  event: ['channel', 'title', 'doc'],
  unposted: ['title', 'doc'],
};

/**
 * Throws if the spec is internally inconsistent: unknown or missing keys, dangling channel/group
 * references, or a type listed as both posted and unposted. `unposted` maps type to `{title, doc}` for
 * types that never post a notification; `deprecated` marks one whose setting can no longer be changed.
 * A `settingsChannel` names the channel whose settings section lists the type: on a channel it folds
 * that channel's types into another, and on an unposted type it gives the type a section. It must
 * name a channel that has no `settingsChannel` of its own.
 */
function validate(spec) {
  const errors = [];
  const checkKeys = (label, obj, kind) => {
    Object.keys(obj).forEach(key => {
      if (!KNOWN_KEYS[kind].includes(key)) {
        errors.push(`${label} has unknown key "${key}"`);
      }
    });
    REQUIRED_KEYS[kind].forEach(key => {
      if (obj[key] === undefined) {
        errors.push(`${label} is missing required key "${key}"`);
      }
    });
  };
  checkKeys('root', spec, 'root');
  if (errors.length) {
    throw new Error(`Invalid NotificationEvents.json:\n  ${errors.join('\n  ')}`);
  }
  Object.entries(spec.channelGroups).forEach(([id, group]) => checkKeys(`group ${id}`, group, 'group'));
  Object.entries(spec.channels).forEach(([id, channel]) => {
    checkKeys(`channel ${id}`, channel, 'channel');
    if (!spec.channelGroups[channel.group]) {
      errors.push(`channel ${id} references missing group "${channel.group}"`);
    }
    if (channel.settingsChannel !== undefined) {
      const target = spec.channels[channel.settingsChannel];
      if (!target || channel.settingsChannel === id || target.settingsChannel !== undefined) {
        errors.push(`channel ${id} settingsChannel "${channel.settingsChannel}" must be another top-level channel`);
      }
    }
  });
  Object.entries(spec.events).forEach(([type, event]) => {
    checkKeys(`event ${type}`, event, 'event');
    if (!spec.channels[event.channel]) {
      errors.push(`event ${type} references missing channel "${event.channel}"`);
    }
    if (spec.unposted[type]) {
      errors.push(`type ${type} is in both events and unposted`);
    }
  });
  Object.entries(spec.unposted).forEach(([type, entry]) => {
    checkKeys(`unposted ${type}`, entry, 'unposted');
    if (entry.settingsChannel !== undefined) {
      const target = spec.channels[entry.settingsChannel];
      if (!target || target.settingsChannel !== undefined) {
        errors.push(`unposted ${type} settingsChannel "${entry.settingsChannel}" must be a top-level channel`);
      }
    }
  });
  if (errors.length) {
    throw new Error(`Invalid NotificationEvents.json:\n  ${errors.join('\n  ')}`);
  }
}

/**
 * Escapes a string as a TypeScript literal, matching the repo's Prettier config: single-quoted unless
 * the value has single quotes and no double quotes.
 */
function tsString(value) {
  if (value.includes("'") && !value.includes('"')) {
    return JSON.stringify(value);
  }
  return `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`;
}

/** Escapes a string as a double-quoted Swift literal. */
function swiftString(value) {
  return JSON.stringify(value);
}

/** Escapes a string as a double-quoted Kotlin literal, including `$` so templates stay literal. */
function kotlinString(value) {
  return JSON.stringify(value).replace(/\$/g, '\\$');
}

/** Renders an optional string as a Swift literal or `nil`. */
function swiftOptional(value) {
  return value === undefined ? 'nil' : swiftString(value);
}

/** Renders an optional string as a Kotlin literal or `null`. */
function kotlinOptional(value) {
  return value === undefined ? 'null' : kotlinString(value);
}

/**
 * Returns the generated TypeScript source: the `NotificationTypeData` enum, merged with a namespace
 * holding the channel names and the spec (title, doc, channel, route path) for every type.
 */
function renderTypeScript(spec) {
  validate(spec);
  const entries = {...spec.events, ...spec.unposted};
  const lines = [HEADER, ''];
  lines.push(
    '/** The type of event a notification socket message describes. Cases are sourced from Swiftarr. */',
    'export enum NotificationTypeData {',
  );
  Object.entries(entries).forEach(([type, entry], index) => {
    if (index > 0) {
      lines.push('');
    }
    if (entry.note) {
      entry.note.split('\n').forEach(line => lines.push(`  // ${line}`));
    }
    lines.push(`  /** ${entry.doc} */`, `  ${type} = ${tsString(type)},`);
  });
  lines.push('}', '');
  lines.push(
    'export namespace NotificationTypeData {',
    '  /** ID of a notification channel, as posted on Android. */',
    '  export type Channel =',
    ...Object.keys(spec.channels).map(
      (id, index, ids) => `    | ${tsString(id)}${index === ids.length - 1 ? ';' : ''}`,
    ),
    '',
    '  /** Display name of each channel. */',
    '  export const channelNames: Record<Channel, string> = {',
  );
  Object.entries(spec.channels).forEach(([id, channel]) => {
    lines.push(`    ${id}: ${tsString(channel.name)},`);
  });
  lines.push(
    '  };',
    '',
    '  /** What specs/NotificationEvents.json says about one notification type. */',
    '  export interface Spec {',
    '    /** User-facing title, matching the push notification title. */',
    '    title: string;',
    '    /** What the event means, from the JSON `doc`. */',
    '    doc: string;',
    '    /** Channel the notification posts to. Undefined for a type that never posts one. */',
    '    channel?: Channel;',
    '    /**',
    '     * Channel whose section the settings screen lists this type in. It differs from `channel` when',
    "     * the spec folds the type's channel into another, and is undefined for an unposted type with no",
    '     * section.',
    '     */',
    '    settingsChannel?: Channel;',
    '    /** App route path the notification opens, with `{placeholders}` for the IDs it needs. */',
    '    url?: string;',
    '    /** The type is no longer used, so its setting cannot be changed. */',
    '    deprecated?: boolean;',
    '  }',
    '',
    '  /** The spec for every type, posted or not. */',
    '  export const specs: Record<NotificationTypeData, Spec> = {',
  );
  Object.entries(entries).forEach(([type, entry]) => {
    const fields = [`title: ${tsString(entry.title)}`, `doc: ${tsString(entry.doc)}`];
    if (entry.channel !== undefined) {
      fields.push(`channel: ${tsString(entry.channel)}`);
    }
    const settingsChannel =
      entry.channel !== undefined
        ? (spec.channels[entry.channel].settingsChannel ?? entry.channel)
        : entry.settingsChannel;
    if (settingsChannel !== undefined) {
      fields.push(`settingsChannel: ${tsString(settingsChannel)}`);
    }
    if (entry.url !== undefined) {
      fields.push(`url: ${tsString(entry.url)}`);
    }
    if (entry.deprecated) {
      fields.push('deprecated: true');
    }
    lines.push(`    [NotificationTypeData.${type}]: {`, ...fields.map(field => `      ${field},`), '    },');
  });
  lines.push(
    '  };',
    '',
    '  /**',
    '   * Returns the user-facing title for a notification type, as shown in the notification log. Falls',
    '   * back to the raw type string for unrecognized types (e.g. `unknown`).',
    '   */',
    '  export const getTitle = (type: string): string => specs[type as NotificationTypeData]?.title ?? type;',
    '',
    '  /**',
    '   * Returns the app route path (e.g. `/seamail/<id>`) that a notification event opens, the same one',
    '   * its push notification opens. Undefined when the type has no destination, or when its path needs',
    '   * more than the content ID (e.g. an incoming call).',
    '   */',
    '  export const getUrl = (type: string, contentID: string): string | undefined => {',
    "    const url = specs[type as NotificationTypeData]?.url?.replace('{contentID}', contentID);",
    "    return url && !url.includes('{') ? url : undefined;",
    '  };',
    '}',
    '',
  );
  return lines.join('\n');
}

/**
 * Returns the generated Swift source: the `NotificationTypeData` enum, the event spec struct and the
 * exhaustive per-type switch.
 */
function renderSwift(spec) {
  validate(spec);
  const unposted = Object.keys(spec.unposted);
  const entries = {...spec.events, ...spec.unposted};
  const lines = [HEADER, '', 'import Foundation', ''];
  // No raw type on purpose: the synthesized Codable has to match the server's `{"seamailUnreadMsg": {}}`.
  lines.push(
    '/// The type of event a notification socket message describes. Cases are sourced from Swiftarr.',
    'enum NotificationTypeData: Codable {',
  );
  Object.entries(entries).forEach(([type, entry], index) => {
    if (index > 0) {
      lines.push('');
    }
    if (entry.note) {
      entry.note.split('\n').forEach(line => lines.push(`\t// ${line}`));
    }
    lines.push(`\t/// ${entry.doc}`, `\tcase ${type}`);
  });
  lines.push('}', '');
  lines.push(
    '/// How a `NotificationTypeData` is posted as a notification. URL templates use `{contentID}`.',
    'struct NotificationEventSpec {',
    '\tlet title: String',
    '\tlet url: String?',
    '\tlet markAsReadUrl: String?',
    '\tlet channel: String',
    '\tlet autoCancel: Bool',
    '\tlet ongoing: Bool',
    '\tlet messaging: Bool',
    '}',
    '',
    'extension NotificationTypeData {',
    '\t/// The event spec for this type, or nil when the type never posts a notification. The enum and this',
    '\t/// switch are generated from the same JSON, so every case is covered.',
    '\tvar eventSpec: NotificationEventSpec? {',
    '\t\tswitch self {',
  );
  Object.entries(spec.events).forEach(([type, event]) => {
    lines.push(
      `\t\tcase .${type}:`,
      '\t\t\treturn NotificationEventSpec(',
      `\t\t\t\ttitle: ${swiftString(event.title)},`,
      `\t\t\t\turl: ${swiftOptional(event.url)},`,
      `\t\t\t\tmarkAsReadUrl: ${swiftOptional(event.markAsReadUrl)},`,
      `\t\t\t\tchannel: ${swiftString(event.channel)},`,
      `\t\t\t\tautoCancel: ${event.autoCancel ?? true},`,
      `\t\t\t\tongoing: ${event.ongoing ?? false},`,
      `\t\t\t\tmessaging: ${event.messaging ?? false}`,
      '\t\t\t)',
    );
  });
  unposted.forEach(type => {
    lines.push(`\t\tcase .${type}:`, '\t\t\treturn nil');
  });
  lines.push('\t\t}', '\t}', '');
  const allTypes = [...Object.keys(spec.events), ...unposted];
  lines.push(
    '\t/// The string form of this type, matching the TypeScript enum values.',
    '\tvar rawValue: String {',
    '\t\tswitch self {',
  );
  allTypes.forEach(type => lines.push(`\t\tcase .${type}: return ${swiftString(type)}`));
  lines.push(
    '\t\t}',
    '\t}',
    '',
    '\t/// Creates a type from its string form, or nil when it is unknown.',
    '\tinit?(rawValue: String) {',
    '\t\tswitch rawValue {',
  );
  allTypes.forEach(type => lines.push(`\t\tcase ${swiftString(type)}: self = .${type}`));
  lines.push('\t\tdefault: return nil', '\t\t}', '\t}', '}', '');
  return lines.join('\n');
}

/** Returns the generated Kotlin source: the literal `NotificationEvents` table. */
function renderKotlin(spec) {
  validate(spec);
  const lines = [HEADER, '', 'package com.tricordarr.push', ''];
  lines.push(
    '/** The notification event table generated from `specs/NotificationEvents.json`. */',
    'object NotificationEventTable {',
    '  val table: NotificationEvents = NotificationEvents(',
    '    channelGroups = listOf(',
  );
  Object.entries(spec.channelGroups).forEach(([id, group]) => {
    lines.push(
      `      ChannelGroupSpec(${kotlinString(id)}, ${kotlinString(group.name)}, ${kotlinString(group.description)}),`,
    );
  });
  lines.push('    ),', '    channels = listOf(');
  Object.entries(spec.channels).forEach(([id, channel]) => {
    const pattern = channel.vibrationPattern
      ? `longArrayOf(${channel.vibrationPattern.map(n => `${n}L`).join(', ')})`
      : 'null';
    lines.push(
      '      ChannelSpec(',
      `        id = ${kotlinString(id)},`,
      `        name = ${kotlinString(channel.name)},`,
      `        groupId = ${kotlinString(channel.group)},`,
      `        description = ${kotlinString(channel.description)},`,
      `        badge = ${channel.badge ?? true},`,
      `        vibrationPattern = ${pattern},`,
      '      ),',
    );
  });
  lines.push('    ),', '    events = mapOf(');
  Object.entries(spec.events).forEach(([type, event]) => {
    lines.push(
      `      ${kotlinString(type)} to EventSpec(`,
      `        type = ${kotlinString(type)},`,
      `        channel = ${kotlinString(event.channel)},`,
      `        title = ${kotlinString(event.title)},`,
      `        url = ${kotlinOptional(event.url)},`,
      `        markAsReadUrl = ${kotlinOptional(event.markAsReadUrl)},`,
      `        autoCancel = ${event.autoCancel ?? true},`,
      `        ongoing = ${event.ongoing ?? false},`,
      `        messaging = ${event.messaging ?? false},`,
      '      ),',
    );
  });
  lines.push('    ),', '  )', '}', '');
  return lines.join('\n');
}

/** Returns the [path, rendered text] pairs for every generated file. */
function renderAll(spec) {
  return [
    [TS_PATH, renderTypeScript(spec)],
    [SWIFT_PATH, renderSwift(spec)],
    [KOTLIN_PATH, renderKotlin(spec)],
  ];
}

/** CLI entry: writes the generated files, or with `--check` verifies they are up to date. */
function main() {
  const spec = JSON.parse(fs.readFileSync(SPEC_PATH, 'utf8'));
  const outputs = renderAll(spec);
  if (process.argv.includes('--check')) {
    const stale = outputs.filter(([file, text]) => !fs.existsSync(file) || fs.readFileSync(file, 'utf8') !== text);
    if (stale.length) {
      stale.forEach(([file]) => console.error(`Stale: ${path.relative(ROOT, file)}`));
      console.error('Run `npm run codegen:notifications` and commit the result.');
      process.exit(1);
    }
    return;
  }
  outputs.forEach(([file, text]) => {
    fs.mkdirSync(path.dirname(file), {recursive: true});
    fs.writeFileSync(file, text);
    console.log(`Wrote ${path.relative(ROOT, file)}`);
  });
}

if (require.main === module) {
  main();
}

module.exports = {renderTypeScript, renderSwift, renderKotlin, SPEC_PATH, TS_PATH, SWIFT_PATH, KOTLIN_PATH};
